-- Run from any directory: lua /path/to/Arch/stdspec/tools/generate_asmtk.lua [--check]
-- Normal builds consume checked-in outputs and do not need Lua or Boost.JSON.
local directory = assert(arg[0]:match("^(.*[/\\])"), "invoke using the script path") .. "../"
package.path = directory .. "?.lua;" .. package.path
local document = require("asmtk.amd64").document
local json = require("asmtk.serialize")
local lines = {
    "// Generated by Arch/stdspec/tools/generate_asmtk.lua; do not edit.",
    "#pragma once", '#include "../../Encoding.hpp"',
    "namespace symspec::encoding::amd64 {",
    "inline constexpr Register registers[] = {",
}
for _, r in ipairs(document.registers) do
    lines[#lines + 1] = string.format('    {"%s", %d, %d},', r.name, r.enc, r.width)
end
lines[#lines + 1] = "};"
lines[#lines + 1] = "inline constexpr Encoding encodings[] = {"
for _, e in ipairs(document.asmtk.encodings) do
    local mask = 0
    for _, w in ipairs(e.widths) do mask = mask | ({[8] = 1, [32] = 2, [64] = 4})[w] end
    local bytes = {}
    for _, b in ipairs(e.opcode) do bytes[#bytes + 1] = string.format("0x%02x", b) end
    lines[#lines + 1] = string.format('    {"%s", Form::%s, %d, {%s}, %d, %d, %d, %s, %d, "%s"},',
        e.mnemonic, e.form, mask, table.concat(bytes, ", "), #e.opcode, e.group, e.reg_operand,
        tostring(e.rex_w), e.relocation, e.implicit_register)
end
lines[#lines + 1] = "};"
lines[#lines + 1] = "} // namespace symspec::encoding::amd64"
local function output(path, contents)
    if arg[1] == "--check" then
        local file = assert(io.open(path, "rb"))
        local current = file:read("*a")
        file:close()
        assert(current == contents, "stale generated architecture data: " .. path)
    else
        local file = assert(io.open(path, "wb"))
        assert(file:write(contents))
        assert(file:close())
    end
end
assert(arg[1] == nil or arg[1] == "--check", "usage: generate_asmtk.lua [--check]")
output(directory .. "asmtk/AMD64.hpp", table.concat(lines, "\n") .. "\n")
output(directory .. "asmtk/amd64.json", json(document) .. "\n")
